window.TRYCKTRACK_QUESTION_BANK = (window.TRYCKTRACK_QUESTION_BANK || []).concat([{"id":"ginecologia-inep-001","number":1,"area":"Ginecologia","source":"INEP","sourceCode":"4000281696","stem":"Mulher, 36 anos, casada, nulípara, comparece à consulta em Unidade Básica de Saúde para iniciar uso de método contraceptivo. Apresenta hipertensão arterial sistêmica e lúpus eritematoso sistêmico com anticorpo antifosfolípide positivo. Relata ciclos menstruais regulares e última menstruação há 1 semana. Ao exame: IMC 32 kg/m²; PA 170 x 100 mmHg; FC 88 bpm; FR 20 irpm e erupção em \"asa de borboleta\" em região malar. Diante desse caso clínico, além do uso de preservativos, qual é o método contraceptivo mais indicado?","options":{"A":"Anel vaginal.","B":"Injetável combinado.","C":"Implante de progesterona.","D":"Dispositivo intrauterino de cobre."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-002","number":2,"area":"Ginecologia","source":"INEP","sourceCode":"4000281691","stem":"Mulher, 39 anos, assintomática, comparece à Unidade Básica de Saúde para consulta de rotina. O histórico da paciente registra dois exames citopatológicos anteriores consecutivos, realizados há 3 e 4 anos, respectivamente, com resultados normais. Ela questiona sobre a necessidade de realizar o exame preventivo (papanicolau). Considerando o novo protocolo de rastreamento de câncer de colo uterino do Ministério da Saúde, qual é a indicação adequada para essa paciente?","options":{"A":"Realizar a coleta de material vaginal para pesquisa de DNA-HPV e, caso o resultado seja negativo, orientar o retorno para novo rastreamento em 5 anos.","B":"Manter o rastreamento com citologia oncótica convencional a cada 3 anos, reservando o teste molecular de DNA-HPV para casos de ASC-US recorrente.","C":"Solicitar a citologia em conjunto com a pesquisa de DNA-HPV e, se houver discordância entre os métodos, encaminhar para colposcopia.","D":"Autocoleta de material vaginal para pesquisa de DNA-HPV e, caso o resultado seja negativo, dispensar a paciente de novos exames de rastreamento."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-003","number":3,"area":"Ginecologia","source":"INEP","sourceCode":"4000281687","stem":"Adolescente de 16 anos, com útero didelfo, 15 dias após parto vaginal sem intercorrências, procura Unidade Básica de Saúde desejando iniciar um método contraceptivo eficaz. Nega doenças crônicas e uso de medicamentos. Encontra-se em amamentação exclusiva. Dentre os métodos contraceptivos disponíveis pelo SUS, qual deve ser indicado?","options":{"A":"Dispositivo intrauterino de cobre.","B":"Implante subdérmico de etonogestrel.","C":"Anticoncepcional oral combinado.","D":"Anticoncepcional injetável mensal."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-004","number":4,"area":"Ginecologia","source":"INEP","sourceCode":"4000281642","stem":"Mulher, 38 anos, procura a Unidade Básica de Saúde relatando corrimento vaginal abundante, amarelo-esverdeado, acompanhado de prurido, ardor e desconforto durante a relação sexual. Refere também aumento do odor após a menstruação. Ao exame especular, observa-se colo hiperemiado com aspecto puntiforme. O pH vaginal é 5,5 e o teste de aminas é negativo. Diante do quadro clínico e desses achados, qual deve ser a conduta terapêutica no caso acima?","options":{"A":"Metronidazol 400 mg via oral duas vezes ao dia por 7 dias.","B":"Clindamicina creme intravaginal por 7 dias.","C":"Fluconazol 150 mg via oral em dose única.","D":"Miconazol creme intravaginal por 7 dias."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-005","number":5,"area":"Ginecologia","source":"INEP","sourceCode":"4000281632","stem":"Mulher, 47 anos, G3 PV2 PC1 A0, comparece ao ambulatório de Ginecologia referindo sangramento uterino anormal há 4 anos. Menarca aos 11 anos, coitarca aos 18 anos. Beta HCG sérico realizado há 3 dias, com resultado negativo. Traz ultrassonografia transvaginal com imagem ovalada e pedículo vascularizado em fundo uterino, medindo 0,6 cm. Endométrio com 9 mm de espessura. Realizou histeroscopia para ressecção da lesão. Exame histopatológico evidenciou projeção digitiforme de tecido glandular, com pedículo vascular. Qual é o provável diagnóstico dessa paciente?","options":{"A":"Leiomioma.","B":"Pólipo.","C":"Hiperplasia endometrial.","D":"Carcinoma de endométrio."},"answer":"B","explanation":"","needsVisualReview":true},{"id":"ginecologia-inep-006","number":6,"area":"Ginecologia","source":"INEP","sourceCode":"4000281625","stem":"Mulher, 42 anos, G3P3, comparece à consulta ginecológica para apresentar resultado de citologia cervical coletada há 1 mês, assim descrita: Adequabilidade da amostra: satisfatória Epitélios representados na amostra: células escamosas, glandulares e metaplásicas. Microbiologia: mista, constituída por cocos e bacilos. Diagnóstico descritivo: células glandulares atípicas de significado indeterminado (AGC). Sem queixas no momento. Na última citologia cervical coletada há 3 anos, não havia alterações. Com base no resultado de citologia cervical dessa paciente, a conduta adequada é","options":{"A":"solicitar pesquisa de HPV de alto risco e repetir citologia em 6 meses.","B":"realizar cauterização cervical e repetir citologia em 12 meses.","C":"solicitar ultrassonografia transvaginal e encaminhar à colposcopia.","D":"realizar biópsia cervical e encaminhar à colposcopia."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-007","number":7,"area":"Ginecologia","source":"INEP","sourceCode":"4000281624","stem":"Homem trans, 30 anos, em uso de testosterona injetável há 6 anos, comparece à Unidade Básica de Saúde para consulta de rotina. Ele possui útero e colo uterino e nunca realizou exame citopatológico devido a medo da dor e a desconforto com o procedimento. Ao exame físico, observa-se atrofia genital importante. O paciente deseja realizar o exame preventivo. No município ainda não está implantada a detecção de DNA-HPV. Nesse caso, a conduta adequada, com a respectiva justificativa, é","options":{"A":"orientar o uso de estrogênio tópico vaginal por 1 a 2 semanas antes da coleta, para reduzir a atrofia e o desconforto.","B":"dar opção de não realizar o exame especular, pois o uso prolongado de testosterona atrofia a zona de transformação.","C":"recomendar dilatação vaginal progressiva com vela de Hegar antes da coleta do exame citopatológico.","D":"vacinar contra HPV, pois tem equivalência na prevenção do câncer de colo de útero."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-008","number":8,"area":"Ginecologia","source":"INEP","sourceCode":"4000281618","stem":"Mulher, 51 anos, comparece à consulta ginecológica na Unidade Básica de Saúde para apresentar mamografia realizada há 1 mês. Não apresenta queixas relacionadas à mama e não possui alterações no exame físico. Nega comorbidades e histórico familiar de doenças mamárias ou oncológicas. Mamografia bilateral. Mama esquerda: parênquima fibroglandular denso. Presença de calcificações pleomórficas finas, com distribuição segmentar, no quadrante ínferomedial. Mama direita: parênquima Kbroglandular denso. Ausência de achados significativos. Mamografia BI-RADS 4C. Considerando os achados mamográficos, qual é a conduta recomendada?","options":{"A":"Solicitar avaliação complementar com ressonância magnética.","B":"Manter seguimento conforme a rotina habitual de rastreamento.","C":"Repetir a mamografia bilateral em 6 meses para controle evolutivo.","D":"Encaminhar a paciente para serviço especializado em mastologia."},"answer":"D","explanation":"","needsVisualReview":true},{"id":"ginecologia-inep-009","number":9,"area":"Ginecologia","source":"INEP","sourceCode":"4000281611","stem":"Mulher, 22 anos, é atendida no serviço de emergência hospitalar, encaminhada pela Unidade de Pronto Atendimento, com história de dor pélvica intensa há 5 dias, febre alta persistente, náuseas e vômitos. Relata corrimento vaginal purulento e piora progressiva do quadro, apesar de ter iniciado antibiótico oral há 48 horas. Ao exame físico, apresenta-se toxemiada, com dor abdominal difusa, defesa à palpação e dor intensa à mobilização do colo uterino. Ultrassonografia pélvica evidencia massa anexial complexa sugestiva de abscesso tubo-ovariano, medindo 3 cm de diâmetro. Qual é a conduta adequada nesse cenário?","options":{"A":"Internar a paciente para antibioticoterapia intravenosa de amplo espectro, com cobertura para gonococo, clamídia e anaeróbios, e monitorar resposta clínica.","B":"Manter o esquema antibiótico oral previamente iniciado, associar analgésicos e antitérmico, e reavaliar em 48 horas no ambulatório.","C":"Internar a paciente e manter o esquema antibiótico oral previamente iniciado até a confirmação microbiológica.","D":"Indicar tratamento antifúngico associado a antibiótico oral, considerando a sobreposição frequente entre DIP e vulvovaginites fúngicas."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-010","number":10,"area":"Ginecologia","source":"INEP","sourceCode":"4000281604","stem":"Mulher, 23 anos, vida sexual ativa, sem parceiro Kxo, procura atendimento ginecológico com queixa de linfoadenomegalia inguinal dolorosa, com linfonodo à esquerda com supuração e Kstulização por orifícios múltiplos. Relata que no início era uma pápula que evoluiu para uma ferida alguns dias antes de apresentar aumento do linfonodo e da dor na região inguinal. Considerando a situação clínica descrita, qual é o provável agente etiológico?","options":{"A":"Chlamydia trachomatis.","B":"Haemophilus ducreyi.","C":"Klebsiella granulomatis.","D":"Treponema pallidum."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-011","number":11,"area":"Ginecologia","source":"INEP","sourceCode":"4000281603","stem":"Mulher, 49 anos, procura Unidade Básica de Saúde com queixa de irregularidade menstrual há cerca de 1 ano, ondas de calor diárias, sudorese noturna, irritabilidade e dificuldade para dormir. Nega comorbidades, medicações de uso regular, tabagismo, história pessoal ou familiar de câncer de mama ou eventos tromboembólicos. Traz resultado de mamografia recente sem alterações. Ao exame físico, não há alterações relevantes. A abordagem inicial, nesse caso, consiste em","options":{"A":"instituir terapia sistêmica com progestágeno isolado, para controle dos sintomas vasomotores e prevenção cardiovascular.","B":"adotar conduta expectante, aguardando a confirmação laboratorial da menopausa por meio da dosagem sérica do hormônio FSH.","C":"indicar Ktoterapia para alívio dos sintomas vasomotores, pois apresenta eficácia equivalente ao estrogênio na prevenção de fraturas.","D":"propor terapia hormonal, definindo a dose e a via de administração conforme o perfil de risco, com reavaliações periódicas da resposta."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-012","number":12,"area":"Ginecologia","source":"INEP","sourceCode":"4000282628","stem":"Paciente de 30 anos procurou consultório de ginecologia relatando fadiga, dismenorreia progressiva e dispareunia de profundidade. Toque vaginal: útero de volume normal, retroversofletido, dor à mobilização do colo. Com base nessas informações, a principal hipótese diagnóstica é","options":{"A":"doença inflamatória pélvica.","B":"miomatose uterina.","C":"cisto hemorrágico.","D":"endometriose."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-013","number":13,"area":"Ginecologia","source":"INEP","sourceCode":"4000282614","stem":"Paciente de 16 anos comparece ao ambulatório para mostrar os resultados dos exames complementares solicitados na consulta anterior. Está preocupada porque todas as colegas da mesma idade já menstruaram e ela não. O fenótipo é feminino, com pelos pubianos e axilares esparsos. Os exames complementares evidenciam ausência d o útero à ultrassonografia pélvica, dosagem sérica do hormônio folículo estimulante (FSH) normal, dosagem de testosterona sérica compatível com níveis do sexo masculino e cariótipo 46 XY. Com base no quadro clínico e nos dados apresentados, a principal hipótese diagnóstica dessa paciente é","options":{"A":"disgenesia gonadal.","B":"malformação Mulleriana.","C":"obstrução do trato genital.","D":"insensibilidade androgênica."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-014","number":14,"area":"Ginecologia","source":"INEP","sourceCode":"4000282583","stem":"Nulípara de 30 anos, com diagnóstico de lúpus eritematoso sistêmico e história recente de trombose venosa, apresenta ciclos menstruais prolongados de 8 a 10 dias, com intenso sangramento e cólicas fortes, busca orientação sobre métodos contraceptivos. Considerando os critérios de elegibilidade para uso de anticoncepção e o quadro clínico, qual é a melhor opção de contracepção?","options":{"A":"DIU de cobre.","B":"DIU de levonorgestrel.","C":"Anticoncepcional injetável mensal.","D":"Pílula anticoncepcional combinada contínua."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-015","number":15,"area":"Ginecologia","source":"INEP","sourceCode":"4000258838","stem":"Mãe leva a Filha de 13 anos e 15 dias à consulta em Unidade Básica de Saúde (UBS). A Filha demonstra preocupação, pois ainda não menstruou, fato que já ocorreu com todas as suas amigas. No histórico, consta telarca aos 10 anos Relata que há uma semana começou com secreção vaginal transparente e sem odor, que por vezes molhava a roupa íntima. Informa não ter tido relações sexuais até o momento da consulta. Exame físico: índice de massa corporal de 18,5 kg/m ; estatura de 1,58 m; pressão arterial de 115 x 80 mmHg; mamas M3 e pelos pubianos P3 (escala de Tanner). Presença de hímen íntegro com orifício anular. Ausência de nódulos inguinais. De acordo com a história clínica, qual é a conduta adequada?","options":{"A":"Explicar que a adolescente apresenta desenvolvimento normal e que provavelmente terá a sua menarca em breve.","B":"Encaminhar a paciente para atenção secundária, por suspeita de hipogonadismo hipogonadotrófico.","C":"Solicitar dosagem de estrogênio, FSH, LH, cariótipo e exame de imagem.","D":"Iniciar terapia estrogênica para preservação de massa óssea."},"answer":"A","explanation":"","needsVisualReview":true},{"id":"ginecologia-inep-016","number":16,"area":"Ginecologia","source":"INEP","sourceCode":"4000258828","stem":"Paciente de 28 anos, primigesta, teve infecção por Zika vírus com 12 semanas de gestação. A ultrassonografia morfológica, realizada com 23 semanas, revelou microcefalia, redução do diâmetro biparietal, leve aumento dos ventrículos laterais, calcificações subcorticais, redução do volume cerebral e lisencefalia. Diante desse resultado, a paciente Kcou apreensiva e solicitou interrupção da gestação. De acordo com o ordenamento jurídico brasileiro, qual é a conduta adequada nesse caso?","options":{"A":"O procedimento poderá ser feito, mediante solicitação por escrito da gestante.","B":"O procedimento não poderá ser realizado, independentemente da idade gestacional.","C":"O procedimento não poderá ser realizado, por já ter ultrapassado 20 semanas de gestação.","D":"O procedimento poderá ser realizado, após a confirmação do diagnóstico por dois especialistas em medicina fetal."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-017","number":17,"area":"Ginecologia","source":"INEP","sourceCode":"4000258821","stem":"Adolescente de 14 anos comparece à consulta acompanhada da mãe. Estão preocupadas porque, mesmo após 18 meses da menarca, a adolescente ainda apresenta ciclos menstruais irregulares, que variam entre 35 a 90 dias, e sangramento que dura de 3 a 7 dias. A paciente nega Fluxo intenso, dor pélvica significativa ou início da atividade sexual. Apesar do quadro relatado, ela nega prejuízo de suas atividades. Ao exame físico, não foram encontradas alterações significativas. Qual é a conduta adequada nesse caso?","options":{"A":"Fazer uma histeroscopia diagnóstica para afastar a hipótese de lesões endometriais","B":"Dosar TSH, FSH, LH, estradiol e prolactina para afastar a hipótese de distúrbios hormonais","C":"Realizar uma ultrassonografia pélvica para afastar a hipótese de lesões miometriais e ovarianas.","D":"Informar que a principal causa é a anovulação, não sendo necessário exame complementar no momento."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-018","number":18,"area":"Ginecologia","source":"INEP","sourceCode":"4000258814","stem":"Paciente de 43 anos, multípara, 5 partos vaginais, comparece à Unidade Básica de Saúde (UBS) com queixa de “bola por baixo”. Refere que há cerca de 3 meses teve dor, vermelhidão e inchaço na região genital, que evolui com remissão parcial espontânea. No dia da consulta, relata incômodo na relação sexual. Exame físico: tumoração cística de 2,0 cm no maior diâmetro, sem sinais inflamatórios, na altura do vestíbulo vaginal, antes das carúnculas himenais, pouco acima da cicatriz de episiotomia médio-lateral direita. A hipótese diagnóstica e a conduta para esse achado, respectivamente, são","options":{"A":"prolapso de colo uterino; correção com pessário vaginal.","B":"divertículo de uretra; cistoscopia para detectar sua extensão.","C":"cisto de glândula de Bartholin; cirurgia se o incômodo à paciente assim o indicar.","D":"cisto de glândula de Skene; ultrassonografia para verificar a extensão do processo."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-019","number":19,"area":"Ginecologia","source":"INEP","sourceCode":"4000258808","stem":"Quanto ao uso e à indicação do DIU de cobre, no âmbito da atenção primária à saúde, assinale a alternativa correta.","options":{"A":"Pode ser inserido em até 72 horas após o parto.","B":"É indicado como contracepção de emergência em até 72 horas.","C":"Em caso de pós-aborto, é indicado aguardar 40 dias para inserção.","D":"Pode ser inserido a qualquer momento do ciclo menstrual, desde que se certifique ausência de gravidez."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-020","number":20,"area":"Ginecologia","source":"INEP","sourceCode":"4000258807","stem":"Paciente de 21 anos, com vacinação HPV completa, comparece à Unidade Básica de Saúde (UBS) e apresenta resultado da citologia do colo uterino realizada em consulta anterior. O laudo citopatológico descreve: “Atipias celulares escamosas, de significado indeterminado (ASCUS)”. Segundo o preconizado pelo Ministério da Saúde, qual é a conduta?","options":{"A":"Repetir citologia após 6 meses.","B":"Repetir a citologia em 3 anos.","C":"Repetir a citologia após 12 meses.","D":"Realizar colposcopia em até 3 meses."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-021","number":21,"area":"Ginecologia","source":"INEP","sourceCode":"4000240444","stem":"Paciente de 49 anos procura atendimento médico relatando que, há 1 mês, não consegue dormir adequadamente por causa de intensas ondas de calor, o que a deixa cansada, irritada e deprimida. Relata dispareunia de penetração e vagina seca. Fez histerectomia e salpingooforectomia bilateral há 3 meses e exame anatomopatológico revelou: adenomiose, hidrossalpinge em ambas as tubas uterinas, cistos de endometriose em ovário direito e focos de endometriose no peritônio. Nega comorbidades. Nesse caso, a conduta mais indicada é","options":{"A":"fitoterápicos, pelo histórico de adenomiose e endometriose.","B":"antidepressivos tricíclicos, já que a hormonioterapia é contraindicada.","C":"estrogenioterapia exclusiva, uma vez que a paciente passou por histerectomia.","D":"tratamento hormonal estro-progestativo, considerando que a paciente apresentou quadro de endometriose."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-022","number":22,"area":"Ginecologia","source":"INEP","sourceCode":"4000240419","stem":"Mulher de 30 anos é encaminhada pelo médico da unidade básica de saúde (UBS) para avaliação com o ginecologista. Relata corrimento com odor fétido após o término da menstruação, nos últimos três ciclos menstruais, e apresenta o laudo da citologia cervical realizada na UBS: presença de epitélio escamoso e glandular, Tora com lactobacilos e dentro dos limites da normalidade. Ao exame especular, observa-se corrimento abundante homogêneo, com vagina e colo uterino de aspecto normal e sem hiperemia. Teste com hidróxido de potássio, realizado na secreção vaginal, com a percepção de odor fétido e pH superior a 5,0. No exame a fresco da secreção vaginal, observam-se células guia (clue cells) no microscópio. Nesse caso, quais são, respectivamente, o diagnóstico e o tratamento a serem prescritos?","options":{"A":"Vaginose citolítica; tratamento com banho de assento com bicarbonato de sódio.","B":"Tricomoníase; tratamento com metronidazol por via oral, ou em forma de creme vaginal.","C":"Candidíase; tratamento com miconazol creme vaginal, ou com fluconazol por via oral.","D":"Vaginose bacteriana; tratamento com metronidazol por via oral, ou em forma de creme vaginal, ou com clindamicina creme."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-023","number":23,"area":"Ginecologia","source":"INEP","sourceCode":"4000240404","stem":"Mulher de 54 anos procura a unidade de pronto atendimento (UPA) com queixa de dor pélvica e de sangramento vaginal ativo, há 2 dias. Relata preocupação, pois não menstruava há 4 anos. Relata que a menopausa ocorreu aos 50 anos e que tem diabetes mellitus tipo 2, tratada com metformina desde os 41 anos. É sedentária, não fuma e nunca ingeriu bebidas alcoólicas. Apresentou os exames de mamografia e citologia de colo uterino, realizados há 4 meses, que mostraram BIRADS 2 bilateral na mamografia e citologia dentro dos limites da normalidade. Ao exame físico, a paciente encontra-se em bom estado geral, orientada, corada, com pressão arterial de 120 x 70 mmHg, frequência cardíaca de 69 bpm e índice de massa corporal (IMC) de 32,3 kg/m². O exame especular revela pequeno sangramento vermelho vivo, saindo pelo orifício cervical externo, com colo do útero atrófico e sem lesões visíveis. O hemograma realizado na UPA revela os seguintes resultados: Considerando o caso descrito, a conduta adequada é","options":{"A":"solicitar ultrassonografia transvaginal e orientar o retorno à unidade básica de saúde.","B":"solicitar ressonância magnética de pelve e orientar que a paciente procure um ginecologista.","C":"solicitar histeroscopia cirúrgica e orientar a paciente que procure uma unidade básica para ser referenciada.","D":"encaminhar a paciente para hospital, com urgência, para realizar curetagem uterina para controle e avaliação do sangramento."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-024","number":24,"area":"Ginecologia","source":"INEP","sourceCode":"4000240399","stem":"Mulher procura orientação na atenção primária preocupada com risco de câncer de mama. Pede orientação sobre quando deve iniciar rastreamento por mamografia. Relata que sua mãe teve câncer de mama aos 45 anos. Está assintomática e suas mamas não apresentam anormalidades ao exame. Nesse caso, considerando-se o uso racional de exames complementares e a segurança da paciente, qual é a conduta mais adequada?","options":{"A":"Manter realização de exame clínico das mamas anualmente, sem a necessidade de exames complementares, e iniciar avaliação por mamografia após os 40 anos.","B":"Iniciar rastreamento com mamografia a partir dos 40 anos, realizado a cada 2 anos, conforme recomendação para a população geral, devido à ausência de sintomas.","C":"Manter acompanhamento clínico regular anual e iniciar mamografia após os 50 anos, uma vez que a paciente está assintomática e sem sinais clínicos de câncer.","D":"Iniciar rastreamento com mamografia a partir dos 35 anos, uma vez que o histórico de câncer de mama em parente de primeiro grau antes dos 50 anos justifica o início precoce do rastreamento."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-025","number":25,"area":"Ginecologia","source":"INEP","sourceCode":"4000240393","stem":"Paciente de 40 anos vai à unidade básica de saúde (UBS) relatando parto há 15 dias e desejo de inserção de DIU. Nesse caso, assinale a alternativa que indica o momento da inserção e o principal mecanismo de ação do DIU de cobre.","options":{"A":"A partir de 12 semanas após o parto; inibição da nidação ovular devido à alta concentração de cobre e afinamento do endométrio.","B":"De forma imediata no ambulatório de Ginecologia; espessamento do muco cervical, dificultando a mobilidade dos espermatozoides.","C":"No período de 4 a 6 semanas após o parto; ação inflamatória e citotóxica no endométrio pela liberação de íons de cobre na cavidade uterina.","D":"De forma imediata na UBS; concentração de cobre no muco cervical, o que o torna mais Fluido, inibindo a mobilidade dos espermatozoides."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-026","number":26,"area":"Ginecologia","source":"INEP","sourceCode":"4000240384","stem":"Paciente de 35 anos procura atendimento na unidade básica de saúde com ultrassonografia transvaginal que revela uma imagem cística anecóica, em seu ovário direito, medindo aproximadamente 6 cm no maior diâmetro, com contornos regulares e paredes Knas, sem septações, conteúdo sólido ou vascularização interna. A paciente está assintomática, possui ciclos menstruais regulares e Fluxo normal. Nega doenças crônicas ou cirurgias prévias. Diante dessa situação, a conduta adequada é","options":{"A":"realizar dosagem sanguínea do CA 125.","B":"indicar acompanhamento ginecológico de rotina.","C":"indicar realização de ressonância magnética da pelve.","D":"repetir a ultrassonografia transvaginal em até 12 semanas."},"answer":"D","explanation":"","needsVisualReview":true},{"id":"ginecologia-inep-027","number":27,"area":"Ginecologia","source":"INEP","sourceCode":"4000240383","stem":"Paciente de 35 anos, contente por sua primeira gravidez, começa o pré-natal na unidade básica de saúde (UBS) de seu bairro. Durante a consulta de enfermagem, é identificado, no exame das mamas, um nódulo na mama direita. Quando informada sobre esse achado, a paciente relata que sua mãe teve câncer de mama aos 38 anos. Diante desse quadro, a conduta médica indicada é","options":{"A":"requisitar biópsia do nódulo mamário guiada por ultrassonografia.","B":"encaminhar a paciente para o ambulatório de gestação de alto risco.","C":"solicitar ultrassonografia de mamas e considerar realização de mamografia com proteção abdominal.","D":"aguardar o final da gestação para realizar investigação do nódulo a partir de ultrassonografia e de mamografia."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-028","number":28,"area":"Ginecologia","source":"INEP","sourceCode":"4000240379","stem":"Multípara de 43 anos, lactante no 2o mês de amamentação, procura atendimento afirmando área de hiperemia e dor no quadrante superior-lateral de mama esquerda, há 5 dias. Relata que, inicialmente, a área afetada era próxima à aréola e que depois foi se estendendo para a região axilar homolateral. Verifica-se ponto de Flutuação e adenopatia dolorosa na axila esquerda. Paciente febril no momento do atendimento. Diante desse quadro, deve-se realizar","options":{"A":"drenagem cirúrgica sobre o ponto de flutuação, com prosseguimento de amamentação em ambas as mamas.","B":"drenagem com agulha Kna guiada por ultrassonografia, com prosseguimento de amamentação pela mama contralateral.","C":"antibioticoterapia durante 7 dias, com lactação mantida, desde que o leite produzido pela mama afetada seja fervido antes de oferecê-lo.","D":"mamografia para descartar carcinoma inflamatório de mama, seguida de punção esvaziadora e de suspensão de amamentação até o resultado do anatomopatológico."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-029","number":29,"area":"Ginecologia","source":"INEP","sourceCode":"4000240369","stem":"Mulher de 45 anos, G2P2, retorna ao ambulatório de ginecologia do hospital escola para o resultado da biópsia de colo uterino realizada há 20 dias. A biópsia evidenciou NIC III, sendo a paciente informada pela residente que ela terá que realizar uma conização do colo uterino para remoção da lesão e prevenção do câncer. Após as explicações, a paciente solicita que já se faça histerectomia para evitar problemas futuros. Diante da solicitação da paciente, a médica deverá informar que a","options":{"A":"histerectomia é um procedimento mais indicado do que a conização, por se tratar de um tumor in situ.","B":"histerectomia é um procedimento mais indicado do que a conização, já que a paciente tem prole constituída.","C":"conização é um procedimento menos invasivo e necessário para afastar a hipótese de microinvasão pelo tumor.","D":"conização é um procedimento menos invasivo e suficiente para o tratamento da paciente, uma vez que se trata de um tumor in situ."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-030","number":30,"area":"Ginecologia","source":"INEP","sourceCode":"4000240364","stem":"Mulher de 60 anos é encaminhada para atendimento especializado por ter apresentado 4 episódios de sangramento vaginal. Ela está lúcida, orientada, sem queixas e com autonomia em sua vida pessoal e social. Apresentou uma ultrassonografia transvaginal com endométrio de 12 mm de espessura e heterogêneo. Foi indicada histeroscopia diagnóstica, mas a paciente recusa-se a fazer porque acha que o sangramento é normal. Nesse caso, o médico deve","options":{"A":"dizer à paciente que respeitará sua decisão e evitar discutir com ela o diagnóstico provável.","B":"informar à paciente que existe a possibilidade de ser câncer e reforçar a necessidade do exame.","C":"esclarecer para a família a necessidade do exame, mas omitir o diagnóstico provável para a paciente.","D":"orientar que, caso ela se recuse a fazer o exame, será necessário procurar outro serviço para acompanhamento."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-031","number":31,"area":"Ginecologia","source":"INEP","sourceCode":"4000240359","stem":"Mulher de 45 anos está em acompanhamento no ambulatório de mastologia de um hospital escola devido ao diagnóstico de câncer de mama há 3 anos. Fez tratamento cirúrgico e radioterapia e, no momento, faz uso apenas de tamoxifeno. Tem apresentado Fluxos menstruais a cada 15-20 dias, com volume aumentado há 2 meses. Relata que, antes do tratamento do câncer de mama, só menstruava duas vezes por ano ou quando usava pílula contraceptiva. Apresenta um IMC de 28 kg/m², exame especular sem lesões visíveis e sem sangramento ativo e toque vaginal normal. Solicitada ultrassonografia transvaginal, Kcou evidenciado endométrio heterogêneo de 15 mm e ovário direito com folículo de 23 mm. Nesse caso, a conduta médica adequada é","options":{"A":"inserir DIU hormonal.","B":"suspender o tamoxifeno.","C":"indicar estudo histológico do endométrio.","D":"prescrever progestogênio em altas doses."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-032","number":32,"area":"Ginecologia","source":"INEP","sourceCode":"4000223968","stem":"Uma paciente de 55 anos, histerectomizada, vai à consulta referindo sintomas climatéricos intensos há 2 anos. Ela relata fazer tratamento com anti-inflamatório para osteoartrite coxofemoral, nega ter hipertensão, diabetes e dislipidemia. Nega antecedentes familiares de câncer de mama ou de ovários, mas relata ter antecedentes de doença de Alzheimer por parte de sua mãe e de sua tia materna. A paciente informa estar interessada em iniciar terapia hormonal (TH) para menopausa. Considerando o caso apresentado, assinale a alternativa que traz a melhor orientação relativa a indicação de TH.","options":{"A":"Orientar a TH isolada com raloxifeno por via oral, devido aos seus benefícios para a cognição.","B":"Indicar o uso de estradiol por via transdérmica, para a redução do risco de osteoporose.","C":"Receitar a TH combinada, estradiol e progesterona, via oral, para proteção endometrial.","D":"Prescrever tratamentos não hormonais, pois ela é histerectomizada e usuária crônica de anti-inflamatórios."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-033","number":33,"area":"Ginecologia","source":"INEP","sourceCode":"4000223963","stem":"Uma paciente de 23 anos, G3 P3, sem antecedentes mórbidos, procura atendimento em ambulatório de planejamento familiar manifestando desejo de laqueadura tubária. Durante a consulta, refere não desejar orientações sobre outros métodos por já estar decidida. De acordo com a lei de planejamento familiar, o profissional de saúde deverá","options":{"A":"prescrever contraceptivo hormonal, pois a paciente não se enquadra nos casos permitidos pela legislação brasileira para laqueadura tubária.","B":"informar a paciente de que é necessária a autorização expressa do cônjuge para a realização da laqueadura tubária.","C":"oferecer informações sobre outros métodos anticoncepcionais para que a paciente possa fazer livre escolha entre métodos reversíveis e irreversíveis.","D":"ofertar orientações sobre métodos anticoncepcionais reversíveis, pois a paciente não se enquadra nos casos permitidos pela legislação brasileira para laqueadura tubária."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-034","number":34,"area":"Ginecologia","source":"INEP","sourceCode":"4000223943","stem":"Uma paciente nulípara de 30 anos vai à consulta na unidade básica de saúde para mostrar seu exame citológico de colo uterino. O resultado constata a presença de células escamosas, glandulares e metaplásicas e atipias nucleares limítrofes (ASCUS). Nesse caso, a conduta médica adequada é","options":{"A":"indicar que a paciente repita o exame citológico em 6 meses.","B":"indicar que a paciente realize biópsia dirigida pelo teste de Schiller.","C":"encaminhar a paciente para acompanhamento em serviço terciário.","D":"encaminhar a paciente para realização de conização do colo uterino."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-035","number":35,"area":"Ginecologia","source":"INEP","sourceCode":"4000223939","stem":"Um adolescente de 15 anos procura o pronto-atendimento relatando ter sido vítima de violência sexual em uma festa. Ele relata que foi abusado, sob coação, por um desconhecido maior de idade. Ao exame físico, verifica-se sinais vitais normais. Na inspeção da região perineal, nota-se uma fissura anal apresentando pequeno sangramento. Nesse caso, o tratamento adequado para infecções sexualmente transmissíveis não virais a ser prescrito ao paciente é","options":{"A":"benzilpenicilina benzatina, ceftriaxona, azitromicina e metronidazol.","B":"amoxicilina com clavulanato, cefaclor, azitromicina e ciprofloxacino.","C":"benzilpenicilina benzatina, cefaclor, clindamicina e metronidazol.","D":"amoxicilina com clavulanato, ceftriaxona, clindamicina e ciprofloxacino."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-036","number":36,"area":"Ginecologia","source":"INEP","sourceCode":"4000223928","stem":"Uma mulher de 35 anos, nuligesta, vai à consulta em ambulatório de dor pélvica crônica de hospital universitário com queixa de dismenorreia progressiva e de hematoquezia quando está menstruada. Relata que as cólicas menstruais pioraram há 5 anos e que precisou procurar o pronto-socorro em duas ocasiões por dor pélvica forte e necessidade de medicação intravenosa. Afirma não fazer uso de contracepção hormonal, por não ter atividade sexual há 10 anos. Nega doenças crônicas ou uso de medicações. Refere constipação com piora nos últimos 6 meses, com distensão abdominal. Ao exame físico, observa-se abdome indolor à palpação, exame especular sem lesões visíveis, toque vaginal com dor à mobilização do colo uterino, útero pouco móvel e palpação de nódulos endurecidos e doloridos em fórnice vaginal posterior. Considerando a provável hipótese diagnóstica, a investigação inicial adequada deverá ser com","options":{"A":"tomografia do abdome para a identificação das lesões profundas de endometriose.","B":"laparoscopia para visualização da distorção da anatomia pélvica causada pela endometriose.","C":"histerossonossalpingografia para avaliação da distorção da anatomia pélvica pela endometriose.","D":"ressonância magnética da pelve para mapeamento das lesões profundas de endometriose."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-037","number":37,"area":"Ginecologia","source":"INEP","sourceCode":"4000223913","stem":"Uma adolescente de 17 anos vai a consulta na unidade básica de saúde referindo sangramento genital intermitente há 1 mês. Diz que, desde a menarca, que ocorreu aos 12 anos, apresenta ciclos oligomenorreicos, menstruando, no máximo, 4 vezes ao ano. Refere, ainda, possuir pele oleosa e acne. Afirma ter iniciado atividade sexual há 6 meses, com uso irregular d e preservativo masculino nas relações. Ao exame físico, apresenta-se hidratada e em bom estado geral. Ao exame ginecológico, observa-se sangramento coletado por espéculo em fundo vaginal, sem lesões visíveis, toque vaginal com o útero móvel, de tamanho habitual e indolor à mobilização do colo uterino. Considerando esse caso, é correto afirmar que","options":{"A":"a paciente está com sintomas sugestivos de abortamento incompleto, devendo-se realizar uma curetagem uterina.","B":"o quadro clínico é compatível com hiperandrogenismo clínico, devendo-se iniciar o uso de acetato de ciproterona.","C":"o quadro clínico é compatível com a síndrome dos ovários policísticos, o sangramento uterino se deve à anovulação crônica.","D":"a paciente está com sangramento uterino anormal, sendo necessário descartar a possibilidade de gravidez não diagnosticada."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-038","number":38,"area":"Ginecologia","source":"INEP","sourceCode":"4000223908","stem":"Uma jovem de 19 anos procura a emergência da maternidade com dor importante no baixo ventre e com discreto sangramento. À triagem, apresenta-se muito abalada, relata ter sofrido violência sexual durante um assalto, há 4 horas, e que o agressor não usou preservativo quando a penetrou. Relata que, ao chegar em casa e contar o ocorrido, sua mãe preferiu levá-la para atendimento médico antes de procurar a delegacia da mulher. Informa nunca ter engravidado, ter ciclos menstruais regulares, ter iniciado vida sexual aos 17 anos, com o ex-namorado, e que, atualmente, está sem relações sexuais há 5 meses. De acordo com a norma técnica do Ministério da Saúde, Prevenção e Tratamento dos Agravos Resultantes da Violência Sexual contra Mulheres e Adolescentes, a conduta médica correta é prescrever a contracepção de emergência com","options":{"A":"levonorgestrel dose única e profilaxia para ISTs não virais e virais, independentemente do status sorológico do agressor.","B":"injetável mensal e profilaxia para ISTs não virais e virais, caso os testes rápidos para sífilis, hepatites e HIV forem negativos.","C":"levonorgestrel dose única, se teste o qualitativo para gravidez for negativo, e profilaxia para ISTs virais com antirretrovirais.","D":"injetável mensal e profilaxia para ISTs não virais e virais, após o retorno da paciente da delegacia com comprovante de exame pericial."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-039","number":39,"area":"Ginecologia","source":"INEP","sourceCode":"4000223903","stem":"Uma adolescente de 16 anos vai a uma consulta no ambulatório de ginecologia referindo ainda não ter menstruado, a despeito de ter apresentado telarca aos 10 anos e pubarca logo em seguida. Ela não tem outras queixas. Sua estatura é de 1,68 m e pesa 65 kg. Apresenta pilificação axilar habitual, acne grau II em face, em tórax e em região dorsal. Ao exame ginecológico, apresenta mamas com configuração normal, distribuição de pelos pubianos adequada para o sexo feminino, órgãos genitais externos sem alterações evidentes e hímen íntegro, com orifício orbicular permeável. Não se procedeu ao toque vaginal. Em relação à avaliação dessa paciente, é correto afirmar que","options":{"A":"a síndrome de Turner deve ser pesquisada, pois seu fenótipo é característico e apresenta amenorreia primária.","B":"a síndrome de Morris (insensibilidade androgênica) é uma hipótese plausível, pois o fenótipo é bastante sugestivo.","C":"a dosagem de estradiol e de hormônio do crescimento deve ser averiguada para proceder ao diagnóstico.","D":"a anomalia mülleriana deve ser investigada, apesar de a genitália externa apresentar aspecto normal."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-040","number":40,"area":"Ginecologia","source":"INEP","sourceCode":"4000223898","stem":"Uma mulher de 19 anos procura um ginecologista com queixa de corrimento vaginal e de dor durante a relação sexual há 2 semanas, por vezes com sangramento pós-coito. Relata que, há 10 dias, começou a sentir queimação, ou dor, ao urinar. Sem histórico de infecção sexualmente transmissível, de gestações ou de abortamentos, faz uso apenas de contraceptivo hormonal, não utiliza métodos de barreira. É tabagista. Ao exame físico, apresenta-se em bom estado geral, com temperatura de 37 °C, frequência cardíaca de 88 batimentos por minuto, sem sinais de dor abdominal. Ao exame ginecológico, observa-se colo hiperemiado com secreção mucopurulenta e sangrante ao toque, manipulação dolorosa do colo. O pH vaginal é normal (< 4,5) e o teste de Whi] (KOH a 10%) é negativo. A partir dos achados apresentados, o diagnóstico etiológico mais provável é","options":{"A":"Candida albicans.","B":"Gardnerella vaginalis.","C":"Neisseria gonorrhoeae.","D":"Trichomonas vaginallis."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-041","number":41,"area":"Ginecologia","source":"INEP","sourceCode":"4000223893","stem":"Uma mulher de 33 anos procura atendimento médico, referindo ter notado há 3 meses, durante autoexame das mamas, nodulação no quadrante súperolateral da mama direita. Não notou aumento de volume ou de tamanho do nódulo durante esse tempo. Relata ter mais facilidade de identificar o nódulo no período que antecede a menstruação e nega outras queixas associadas. É tabagista (10 cigarros/dia), corre – 4 vezes por semana –, engravidou uma única vez (parto normal, há dois anos), amamentou por 6 meses, faz uso de DIU de cobre, com boa adaptação. Sua menarca foi aos 11 anos, sexarca aos 18 anos, possui ciclos regulares (5-28), sua última menstruação foi há 15 dias. Relata história familiar de câncer de ovário (tia materna aos 47 anos) e de câncer de mama (sua mãe aos 42 anos). Ao exame físico, observa-se nódulo palpável em quadrante súperolateral da mama direita, com cerca de 3 cm; móvel, com consistência macia e limites definidos; sem outros achados. O ultrassom de mamas e axilas, realizado 20 dias após a consulta, revelou BIRADS 2 — observada lesão anecóica circunscrita, com reforço acústico posterior, sem septações, sem Fluxo ao Doppler, em quadrante súperolateral da mama direita, medindo 2 cm em seu maior diâmetro. Nesse caso, conforme as recomendações do Ministério da Saúde, quais são, respectivamente, a hipótese diagnóstica e a conduta adequada?","options":{"A":"Fibroadenoma; tranquilizar a paciente e complementar a investigação com ressonância nuclear magnética da mama devido a maior densidade mamária.","B":"Cisto de mama; orientar a cessação de tabagismo, prescrever analgésicos, se necessário, e orientar a paciente que se trata de um quadro benigno da mama.","C":"Mamas normais; salientar a importância do autoexame das mamas como ferramenta importante no rastreamento de câncer se realizado todo mês antes da menstruação.","D":"Adensamento mamário; recomendar cessação de tabagismo, uso de sutiã com suporte adequado e início de rastreamento para câncer de mama, além de solicitar mamografia."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-042","number":42,"area":"Ginecologia","source":"INEP","sourceCode":"4000223888","stem":"Uma mulher de 65 anos, doadora de sangue frequente, vai à consulta ginecológica de rotina referindo ter apresentado lesão endurecida em vulva, sem secreção, não dolorosa, com nódulo inguinal, que regrediu após 15 dias sem nenhum tratamento. No momento da consulta, o teste rápido para sífilis mostrou-se positivo. Nesse caso, a conduta mais adequada para essa paciente é","options":{"A":"solicitar imediatamente o teste de VDRL, para confirmar a doença.","B":"solicitar imediatamente o teste de FTA-ABS, para confirmar a doença.","C":"realizar tratamento com 2,4 milhões de unidades de penicilina benzatina em dose única e fazer controle de cura com VDRL.","D":"realizar tratamento com 2,4 milhões de unidades de penicilina benzatina 1 vez, por semana por 3 semanas, e fazer controle de cura com VDRL."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-043","number":43,"area":"Ginecologia","source":"INEP","sourceCode":"4000223882","stem":"Uma mulher de 50 anos vai a uma consulta na unidade básica de saúde referindo sangramento vaginal contínuo de baixo volume há 2 meses, exacerbado há 20 dias. Em menopausa há 4 anos, sem uso de terapia de reposição hormonal, é hipertensa compensada, sem outras comorbidades. Ao exame físico, eutrófica, sem alterações. Considerando que nesse caso a principal hipótese diagnóstica é uma causa estrutural, qual exame complementar deve ser solicitado para essa paciente?","options":{"A":"Provas de coagulação.","B":"Dosagem de prolactina.","C":"Ultrassonografia da região pélvica.","D":"Dosagem de hormônios da tireoide."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-044","number":44,"area":"Ginecologia","source":"INEP","sourceCode":"4000218475","stem":"Uma paciente com 55 anos, em acompanhamento de rotina, encontra-se no ambulatório de Ginecologia Geral, assintomática e, ao exame físico, apresenta-se normal. Realizada a mamografia de rotina, verifica-se laudo com categoria BIRADS 4, devido à presença de microcalcificações agrupadas. Considerando-se o caso descrito, qual é a conduta adequada?","options":{"A":"Realização de quadrantectomia.","B":"Biopsia para investigação histológica.","C":"Repetição de mamografia em 6 meses.","D":"Complementação com ultrassonografia."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-045","number":45,"area":"Ginecologia","source":"INEP","sourceCode":"4000218445","stem":"Uma mulher com 60 anos, cuja menopausa ocorreu há 8 anos, G2P2, procura a unidade de saúde queixando-se de ter apresentado três episódios de sangramento transvaginal de pequena quantidade nos últimos 2 meses. O exame citopatológico do colo uterino realizado há 6 meses apresentou células escamosas e glandulares e foi negativo para neoplasias. A história patológica pregressa da paciente incluía apenas dislipidemia. O resultado do exame de ecografia transvaginal evidenciou endométrio irregular com 8 mm de espessura. O IMC era de 32 e o exame do abdome e pelve normal. Para condução desse caso, o médico deve","options":{"A":"solicitar histeroscopia diagnóstica.","B":"iniciar terapia hormonal combinada.","C":"iniciar ácido tranexâmico oral e controle citológico.","D":"indicar histerectomia total com anexectomia bilateral."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-046","number":46,"area":"Ginecologia","source":"INEP","sourceCode":"4000218440","stem":"Mulher com 21 anos chega a uma unidade de pronto atendimento relatando dor pélvica há 2 dias, que se intensificou nas últimas 8 horas, após relação sexual. Queixa-se de sangramento vaginal após a relação, evidenciado na consulta. Refere que a última menstruação havia ocorrido há 5 dias, com ciclos anteriores regulares. Ao exame físico, encontrava-se febril (temperatura axilar: 38,7 °C), com sinais de defesa abdominal, e demonstrou que o exame ginecológico foi extremamente doloroso, quando houve mobilização dos anexos e do colo uterino, que apresentava ectocérvice friável e sangrante. A paciente refere dados normais de exames ginecológico e ecográfico realizados há 90 dias. Considerando-se essa história clínica, qual é o diagnóstico mais provável?","options":{"A":"Gravidez ectópica rota.","B":"Doença inflamatória pélvica.","C":"Torção anexial de cisto ovariano.","D":"Rotura de cisto lúteo hemorrágico."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-047","number":47,"area":"Ginecologia","source":"INEP","sourceCode":"4000218425","stem":"Uma paciente com 54 anos, G2 P1 C1, com ligadura tubárea bilateral, comparece à consulta ambulatorial com queixa de fogachos, sudorese noturna, insônia, queda da libido, secura vaginal, fadiga e falta de concentração. Sem outras queixas em seu histórico, verifica-se registro de: menarca aos 13 anos; menopausa aos 50 anos; e de tabagismo (consumo de 10 cigarros/dia) desde os 20 anos, além de história patológica pregressa de hipertensão arterial crônica, em uso de losartana 50mg/dia, com bom controle; e história patológica familiar de osteoporose e diabetes mellitus (mãe), hipertensão arterial e infarto agudo do miocárdio aos 60 anos de idade (pai). A paciente apresenta resultados de exames realizados há 6 meses: mamografia digital bilateral: BIRADS 1; Ultrassonografia transvaginal: útero de 40 cm3 , endométrio homogêneo e de 3 mm de espessura, ovários atróficos; exames laboratoriais: sem alterações. Ao exame físico, observa-se: índice de massa corpórea: 26,4 kg/m²; pressão arterial: 110 x 70 mmHg; hipotrofia em vagina e colo. Considerando-se o caso clínico descrito, qual é a conduta adequada?","options":{"A":"Contraindicar terapia hormonal sistêmica e indicar estriol via vaginal.","B":"Sugerir terapia hormonal sistêmica com estradiol oral e noretindrona.","C":"Contraindicar terapia hormonal sistêmica, orientando mudanças no estilo de vida.","D":"Sugerir terapia hormonal sistêmica com estradiol transdérmico e progesterona micronizada."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-048","number":48,"area":"Ginecologia","source":"INEP","sourceCode":"4000218420","stem":"Uma mulher com 30 anos procura o médico na unidade básica de saúde e, em consulta, relata que, há 9 meses, parou de usar o anticoncepcional oral combinado e que não voltou a menstruar até o momento. Refere também uso desse método contraceptivo por 10 anos e aumento de pelos no corpo. O exame ginecológico, apresenta-se normal. No exame físico, verificam-se: índice de massa corporal de 27 kg/m2 ; pressão arterial de 110 x 72 mmHg; cintura abdominal de 80 cm; acne e hirsutismo moderado. Os exames complementares apresentam os seguintes resultados: Beta-hCG negativo; TSH = 2,5 mUI/L (valor de referência - VR: 0,3 a 4,0 UI/L); prolactina = 18 ng/mL (VR: < 31 ng/mL); FSH = 6 mUI/mL (VR: 2 a 30 mUI/mL). Diante do quadro clínico da paciente, o diagnóstico é de amenorreia secundária por","options":{"A":"falência ovariana prematura.","B":"hipogonadismo hipogonadotrófico.","C":"uso prolongado do anticoncepcional.","D":"anovulação crônica hiperandrogênica."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-049","number":49,"area":"Ginecologia","source":"INEP","sourceCode":"4000218414","stem":"A inserção e a retirada do dispositivo intrauterino (DIU) faz parte da carteira de serviços da atenção primária à saúde. Acerca desse dispositivo, assinale a opção correta.","options":{"A":"O Ministério da Saúde não recomenda a inserção do DIU por enfermeiros.","B":"A inserção do DIU é contraindicada após o procedimento de aborto devido ao risco de infecção.","C":"O DIU de cobre pode ser inserido, como um anticoncepcional de emergência, em até 7 dias a partir do coito sem proteção.","D":"O DIU hormonal pode ser usado para controle de sangramento uterino anormal, para redução da dismenorreia e como método contraceptivo."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-050","number":50,"area":"Ginecologia","source":"INEP","sourceCode":"4000218405","stem":"Uma puérpera, 14 dias pós-parto vaginal, que vem amamentando exclusivamente seu bebê, procura uma unidade básica de saúde referindo dor em mama direita. Ao exame, evidenciam-se pressão arterial de 120 x 70 mmHg, frequência cardíaca de 90 bpm, temperatura axilar de 37,8 °C, mamas túrgidas e com Kssuras nos mamilos, hiperemia, calor e dor na junção dos quadrantes inferiores da mama direita, sem sinais de flutuação. Para o caso dessa paciente, a hipótese diagnóstica e o tratamento adequado são, respectivamente","options":{"A":"galactocele; massagem mamária e manutenção da amamentação.","B":"mastite; analgesia, manutenção da amamentação e antibioticoterapia via oral.","C":"abscesso mamário; antibioticoterapia intravenosa e drenagem da mama direita com sedação.","D":"ingurgitamento mamário; aplicação de compressas frias, interrupção da amamentação e manutenção das mamas bem suspensas."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-051","number":51,"area":"Ginecologia","source":"INEP","sourceCode":"4000218400","stem":"Uma mulher com 70 anos foi encaminhada para o ambulatório de patologia cervical/vulvar por causa de uma lesão avermelhada, pruriginosa, próxima ao clitóris. Fez uso de corticosteroides tópicos e sistêmicos, com melhora parcial do prurido, mas sem alteração da lesão. Também fez uso oral de Fluconazol, sem resposta ao tratamento. O resultado da pesquisa de DNA de HPV foi negativo. Ao exame da paciente, evidenciou-se uma lesão no clitóris medindo 2 cm, eritematosa, com área de descamação, além de líquen escleroso acometendo parte do clitóris e pequenos lábios. A partir da situação apresentada, o médico deve solicitar","options":{"A":"vulvoscopia e realizar a biópsia da lesão.","B":"testes alérgicos e iniciar clobetasol tópico.","C":"cultura de fungos e tratar com cetoconazol tópico.","D":"teste de azul de toluidina e indicar vulvectomia simples."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-052","number":52,"area":"Ginecologia","source":"INEP","sourceCode":"4000218394","stem":"Uma mulher com 42 anos comparece à unidade básica de saúde para consulta com um médico de família e comunidade. Ela possui histórico de irregularidade menstrual, de irritabilidade, de ansiedade, de perda de memória e de fogachos há 6 meses, apresentando sangramento uterino anormal (SUA) há 3 dias, sem sinais de repercussão na estabilidade hemodinâmica. A partir dessas informações e com base nos conhecimentos acerca do sangramento apresentado por essa paciente, assinale a opção correta.","options":{"A":"O SUA é uma condição rara que afeta poucas mulheres no mundo, principalmente aquelas na pré-menopausa, seguidas por aquelas na perimenopausa e na pós-menopausa.","B":"O SUA é uma afecção frequente que pode comprometer a qualidade da vida da mulher em vários aspectos, sendo recomendado, como terapêutica de primeira linha, a histerectomia.","C":"A presença de lesões vaginais e de colo deve ser descartada por meio do exame físico e a hipótese de gestação deve ser excluída, considerando os principais diagnósticos relacionados ao SUA.","D":"O exame complementar que fornece mais dados para a condução dos casos de SUA é a ultrassonografia da região pélvica, com baixa sensibilidade, porém alta especificidade para lesões endometriais em geral."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-053","number":53,"area":"Ginecologia","source":"INEP","sourceCode":"4000218390","stem":"Uma mulher com 35 anos, nuligesta, em uso de anticoncepcional oral há 10 anos, queixa-se de mastalgia há 10 dias. Relata que a última menstruação foi há 25 dias. Na história familiar, refere uma tia com 65 anos que está tratando de câncer de mama há 3 anos. O índice de massa corporal (IMC) dessa paciente é de 32 kg/m² e o exame físico das mamas não apresenta anormalidades. De acordo com o previsto pelo Ministério da Saúde, o acompanhamento dessa paciente deve ser feito com","options":{"A":"ressonância magnética das mamas anualmente.","B":"ultrassonografia mamária bienal após os 40 anos","C":"exame clínico das mamas e mamografia anualmente.","D":"exame clínico anual e mamografia bienal após os 50 anos."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-054","number":54,"area":"Ginecologia","source":"INEP","sourceCode":"4000218385","stem":"Uma paciente com 45 anos, nuligesta, com ciclos menstruais irregulares, é encaminhada da atenção básica para ambulatório especializado de Ginecologia. Ela apresenta ultrassonografia transvaginal que evidencia cisto de 6 cm, com projeção papilar no seu interior, no ovário esquerdo, e que se mostram normais o ovário direito e demais estruturas pélvicas. Considerando-se esse caso, o critério que determinará a investigação cirúrgica será","options":{"A":"o tamanho do cisto.","B":"a idade da paciente.","C":"a projeção papilar do cisto.","D":"a irregularidade menstrual."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-055","number":55,"area":"Ginecologia","source":"INEP","sourceCode":"4000203405","stem":"Uma mulher de 51 anos vem ao ambulatório de referência mencionando fogachos, insônia, irritabilidade e labilidade emocional há 3 meses. A última menstruação foi há 6 meses e nunca usou hormônios. É hipertensa em uso de medicação com níveis tensionais controlados. Realizou revisão ginecológica recentemente, com exames clínico e complementares normais. Após a explanação do médico sobre os riscos e benefícios da terapia hormonal (TH) no climatério, a paciente informa que deseja usar hormônios para alívio da sintomatologia, solicitando um esquema hormonal de menor risco para o seu organismo. Considerando as evidências disponíveis quanto ao perfil farmacológico e clínico dos esquemas de TH, o médico deverá prescrever","options":{"A":"estradiol 1 mg + acetato de noretisterona 0,5 mg, por via oral, contínuo.","B":"estradiol 50 mcg + acetato de noretisterona em adesivo, por via transdérmica, contínuo.","C":"estrogênios equinos conjugados 0,625 mg + acetato de medroxiprogesterona 5 mg, por via oral, contínuo.","D":"estradiol 1 mg em gel, por via transdérmica, contínuo + progesterona natural micronizada 100 mg, por via vaginal, cíclico."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-056","number":56,"area":"Ginecologia","source":"INEP","sourceCode":"4000203404","stem":"Uma paciente de 34 anos, solteira, G2P2A0C0, com ligadura tubária há 4 anos, sem parceria sexual, e sem uso de outros métodos contraceptivos, apresenta aumento de volume menstrual nos últimos 6 ciclos, associado a aumento do período menstrual de 3 para 7 dias. Refere a presença há 5 dias, de sangramento excessivo com coágulos, e aumento do volume há 6 horas, associado à dor abdominal em cólica, astenia, cansaço e fraqueza. A paciente nega possuir doenças prévias ou fazer uso de medicamentos. Apresenta-se em regular estado geral, descorada +/4+, desidratada +/4+, com pressão arterial de 80 × 50 mmHg, frequência cardíaca de 108 batimentos por minuto, sem outras alterações. Ao exame especular, observa-se grande quantidade de sangue saindo pelo orifício cervical externo, e parede vaginal íntegra. Diante disso, o médico de família e comunidade inicia a hidratação com soro Fisiológico 0,9%, 1 000 mL intravenoso, e solicita a remoção da paciente para o serviço de urgência. Com base nesse quadro, quais devem ser, respectivamente, os primeiros exames complementares e a terapêutica medicamentosa inicial a serem ofertados à paciente?","options":{"A":"Hemograma, TSH, ultrassonografia transvaginal; prescrição de acetato de medroxiprogesterona.","B":"TGO, TGP, coagulograma e hemograma; prescrição de desogestrel de uso contínuo.","C":"Coagulograma e ultrassonografia transvaginal; prescrição de ácido mefenâmico.","D":"FSH, LH e prolactina; prescrição de diclofenaco sódico."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-057","number":57,"area":"Ginecologia","source":"INEP","sourceCode":"4000203400","stem":"Uma mulher de 52 anos é encaminhada à atenção secundária com um resultado de mamografia BI-RADS 0. A paciente relata dor e sensibilidade na mama direita e menciona que sua mãe teve câncer de mama. Ao examiná-la, o médico identifica uma massa palpável de cerca de 3 cm, localizada na parte superior da mama. Considerando as orientações definidas pelo Sistema Único de Saúde, qual deve ser a primeira conduta tomada pelo médico?","options":{"A":"Realizar biópsia da lesão.","B":"Repetir a mamografia em 6 meses.","C":"Realizar exame de ultrassonografia.","D":"Realizar punção aspirativa por agulha fina (PAAF) da lesão."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-058","number":58,"area":"Ginecologia","source":"INEP","sourceCode":"4000203395","stem":"Uma paciente de 28 anos, G3P2A1 (partos normais), procura a unidade básica de saúde para informar-se acerca de métodos contraceptivos para o seu caso. Ela refere ter útero didelfo e relata fazer acompanhamento no ambulatório de hematologia por ter tido tromboembolismo pulmonar após COVID-19. Além disso, também faz acompanhamento no ambulatório de reumatologia por possuir lúpus eritematoso sistêmico. A paciente apresenta Fluxo menstrual intenso e não deseja laqueadura, por questões pessoais. Segundo os critérios de elegibilidade, qual método é indicado para o caso dessa paciente?","options":{"A":"Sistema intrauterino de levonogestrel (SIU-l).","B":"Dispositivo intrauterino de cobre (DIU T-Cu).","C":"Pílula de etinilestradiol e gestodeno.","D":"Pílula de progestágeno isolado."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-059","number":59,"area":"Ginecologia","source":"INEP","sourceCode":"4000203390","stem":"Uma mulher de 27 anos vai em consulta por demanda espontânea na unidade básica de saúde com queixa de corrimento vaginal e de prurido há 3 dias. Ela não é fumante nem possui histórico de infecções sexualmente transmissíveis. Sua última menstruação ocorreu há 20 dias. Ao exame físico, a paciente está em bom estado geral, com temperatura de 36,8 °C, frequência cardíaca de 80 batimentos por minuto, sem sinais de dor abdominal nem de alterações ginecológicas ao toque vaginal. Ao exame especular, é observado um corrimento esbranquiçado, sem cheiro forte, grumoso e aderente na parede vaginal e ectocérvice, além de hiperemia da mucosa vaginal. O teste de Whi] (KOH 10%) foi negativo e o pH vaginal estava normal (< 4,5). A partir desses achados, assinale a opção que apresenta o agente etiológico mais provável.","options":{"A":"Candida sp.","B":"Gardnerella vaginalis.","C":"Trichomonas vaginallis.","D":"Chlamydia trachomatis."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-060","number":60,"area":"Ginecologia","source":"INEP","sourceCode":"4000203381","stem":"Durante uma consulta de rotina com o médico da unidade básica de saúde, uma adolescente de 15 anos relata ter iniciado sua vida sexual com o namorado de mesma idade. Ela refere que têm usado preservativo, porém sente-se insegura e gostaria de iniciar o uso de anticoncepcionais orais, assim como suas amigas já o fazem. A paciente não apresenta queixas e não tem antecedentes patológicos pessoais ou familiares. Frequenta o primeiro ano do ensino médio e relata que não gostaria de informar seus pais sobre as questões de sua sexualidade. Considerando o Código de Ética Médica e o Estatuto da Criança e do Adolescente, a conduta correta do médico, nesse caso, é","options":{"A":"optar por não prescrever a anticoncepcão oral, uma vez que a adolescente pretende usar pílula para evitar a gravidez e estará arriscada a contrair infecções sexualmente transmissíveis, caracterizando imaturidade psicológica e risco para si; ele deve reforçar, também, a prática sexual segura e, devido ao risco iminente à saúde da adolescente, está obrigado a informar os responsáveis sobre o motivo da consulta.","B":"ponderar sobre a prescrição de anticoncepção, pois a busca pelo aconselhamento médico é um indício de decisão madura, sendo provável que, em caso de recusa da prescrição, a paciente decida se automedicar; ele deve, também, aproveitar esse momento para abordar a prática sexual segura, assim como deve incentivar o fortalecimento dos laços de comunicação familiar sobre as decisões da adolescente.","C":"decidir por não prescrever a anticoncepção oral, uma vez que não consegue, com base na consulta, julgar a maturidade da adolescente, podendo ser responsabilizado em caso de uso inadequado e de gravidez subsequente; ele deve aproveitar o momento para abordar a prática sexual segura e para manter os princípios de confidencialidade sobre a consulta, já que não há risco de vida iminente.","D":"considerar a prescrição de anticoncepção, visto que a menina já iniciou atividade sexual, aproveitando o momento, também, para abordar a prática sexual segura; ele deve comunicar a adolescente de que o assunto será tratado com seus pais, uma vez que os menores de 16 anos são classificados como “absolutamente incapazes de exercer pessoalmente os atos da vida civil\"."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-061","number":61,"area":"Ginecologia","source":"INEP","sourceCode":"4000203380","stem":"Uma mulher de 25 anos vai à emergência referindo sentir dor em fossa ilíaca esquerda (FIE) há 6 horas. Nega febre, alteração do hábito intestinal ou urinário. Sua última menstruação foi há 15 dias e faz uso de dispositivo intrauterino de cobre há 2 anos. Relata ter ciclos menstruais mensais, parceiro único e ausência de leucorreia. Ao exame físico, apresenta pressão arterial de 120 × 80 mmHg, frequência cardíaca de 90 batimentos por minuto, temperatura axilar de 36,8 °C, dor à palpação superficial e profunda do abdome em FIE com sinais de irritação peritoneal. São realizados teste de gravidez, com resultado negativo, e ultrassonografia transvaginal, a qual evidenciou cisto heterogêneo em ovário esquerdo, de 4 cm, com vascularização periférica ao Doppler, com mínima quantidade de liquido livre em fundo de saco de Douglas. Nessa situação, a conduta terapêutica adequada consiste em realizar","options":{"A":"laparotomia exploradora.","B":"laparoscopia com ooforoplastia.","C":"analgesia e observação hospitalar.","D":"laparoscopia com ooforectomia."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-062","number":62,"area":"Ginecologia","source":"INEP","sourceCode":"4000203377","stem":"Uma paciente de 70 anos foi submetida a histerectomia total transabdominal há 3 meses por prolapso uterino completo. Procura atendimento, com história de perda involuntária de líquido pelo canal vaginal, progressiva, há pouco mais de 2 meses. A micção é normal. A ultrassonografia de pelve demonstra coleção líquida perivesical. Diante do quadro clínico apresentado, qual a principal hipótese diagnóstica?","options":{"A":"Incompetência do assoalho vesical.","B":"Abscesso pélvico pós-operatório.","C":"Seroma pélvico pós-operatório.","D":"Fístula uretero-vaginal."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-063","number":63,"area":"Ginecologia","source":"INEP","sourceCode":"4000203375","stem":"Uma mulher de 58 anos foi atendida pela primeira vez no ambulatório especializado em climatério. Faz uso de terapia hormonal combinada via oral há 6 anos. Interrompeu o uso há 5 meses, mas voltou a usar a medicação devido aos sintomas intensos de climatério, principalmente devido aos fogachos e ao impacto negativo na relação sexual. Há cinco anos foi internada por um quadro de trombose venosa profunda, porém, desde então, não houve outros episódios. Os exames de rotina recentes são apresentados na tabela a seguir: Diante do caso acima, a conduta mais segura é","options":{"A":"interromper a medicação oral e indicar o uso de fitoterápicos para terapia hormonal.","B":"trocar por estrogênio oral isolado e inserir o sistema intrauterino liberador de levonorgestrel.","C":"manter a terapia hormonal oral somente com estrogênio e realizar histeroscopia com biópsia.","D":"interromper o uso da medicação oral e prescrever terapia hormonal combinada com estradiol transdérmico."},"answer":"D","explanation":"","needsVisualReview":true},{"id":"ginecologia-inep-064","number":64,"area":"Ginecologia","source":"INEP","sourceCode":"4000203370","stem":"Uma mulher de 35 anos procura unidade básica de saúde para fazer exame de rastreio de câncer de mama. Ela informa que sua mãe foi diagnosticada com câncer de ovário aos 72 anos e que seu pai faleceu de câncer de intestino. A paciente é nulípara, faz uso de anticoncepcional oral desde a adolescência, é obesa e tabagista há 10 anos fazendo uso de 10 cigarros por dia. Nesse caso, a conduta adequada é","options":{"A":"solicitar mamografia e ultrassonografia de mamas.","B":"examinar as mamas da paciente e solicitar mamografia.","C":"encaminhar a paciente para pesquisa de mutação do gene BRCA1.","D":"examinar as mamas da paciente e orientar o controle clínico periódico a ela."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-065","number":65,"area":"Ginecologia","source":"INEP","sourceCode":"4000203367","stem":"Uma mulher de 59 anos é atendida em unidade de pronto-atendimento, queixando-se de dor lombar contínua, de forte intensidade, de caráter progressivo e com piora no último mês. Realizou tratamento prévio com analgésico e com anti- inflamatório, porém os sintomas persistiram. Ela refere história prévia de tratamento para câncer de mama há 3 anos. N o momento, está sem queixas acerca da mama. O exame físico mostra hiperalgesia aos estímulos em coluna lombar. Radiografia da coluna lombar: lesões líticas. Com base no caso clínico apresentado, a principal hipótese diagnóstica é","options":{"A":"metástase.","B":"tuberculose.","C":"hérnia discal.","D":"fratura vertebral."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-066","number":66,"area":"Ginecologia","source":"INEP","sourceCode":"4000194346","stem":"Uma paciente com 21 anos, nuligesta, comparece à consulta em um centro de saúde com queixa de amenorreia há 6 meses, acne com pústulas, aumento de pelos, principalmente na face e nos membros inferiores. Relata dificuldade em perder peso e ciclos menstruais irregulares e longos desde a menarca. Afirma ser sexualmente ativa. É realizado, durante o atendimento, teste rápido para gravidez, com resultado negativo. Ao exame físico, apresenta índice de massa corpórea de 30 kg/m², pressão arterial de 120 × 70 mmHg. Considerando-se o quadro clínico da paciente, qual é a conduta inicial mais adequada no momento desse atendimento?","options":{"A":"Dosar TSH, T4 livre, prolactina e 17 hidroxiprogesterona, para descartar patologias sistêmicas.","B":"Dosar cortisol livre, dehidroepiandrosterona e perfil metabólico, para confirmar perfil androgênico.","C":"Prescrever etinilestradiol 10 mg 1 vez ao dia, por 10 dias, para descartar causas uterinas de amenorreia.","D":"Iniciar espironolactona 50 mg 2 vezes ao dia e solicitar ultrassonografia, para confirmar diagnóstico de síndrome dos ovários policísticos."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-067","number":67,"area":"Ginecologia","source":"INEP","sourceCode":"4000194341","stem":"A vulvovaginite constitui uma das doenças mais comuns que motivam as mulheres a procurar o/a ginecologista. Nesse contexto, considerando a importância do diagnóstico etiológico, assinale a opção correta.","options":{"A":"Na infecção por clamídea, o corrimento apresenta-se em moderada quantidade com intensa reação inflamatória nas paredes vaginais.","B":"Na tricomoníase, o corrimento é escasso, e o diagnóstico é realizado com base no resultado da bacterioscopia e da cultura de meio vaginal.","C":"Na candidíase vaginal, o corrimento no exame direto apresenta aspecto branco, habitualmente espesso ou grumoso, aderido ao colo e às paredes vaginais.","D":"Na vaginite citolítica, o pH da vagina é maior que 4,5, o corrimento tem aspecto homogêneo, e a bacterioscopia mostra a presença de germes Gram negativos."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-068","number":68,"area":"Ginecologia","source":"INEP","sourceCode":"4000194331","stem":"Uma paciente com 45 anos, casada, G2P2, 2 partos normais, comparece ao ambulatório de ginecologia para avaliação de resultado de ultrassonografia transvaginal que evidenciou útero em anteversoflexão, contornos regulares, miométrio heterogêneo, com pequenos miomas intramurais e subserosos, estando o maior localizado na parede posterior/fúndica, intramural, medindo 2,0 × 1,9 cm; volume uterino de 198,6 cm3 (valor do percentil 95 para a faixa etária e paridade - 136 cm3); ovários de topografia, dimensões e ecotextura usuais; endométrio centrado, regular, medindo 6,8 mm de espessura (normal para faixa etária e paridade). A paciente relata ciclos menstruais regulares de 28 dias, Fluxo moderado com duração de 5 dias, nega dismenorreia ou dispareunia. Afirma que é sexualmente ativa e que o marido é vasectomizado. Para essa paciente, a conduta mais adequada é","options":{"A":"manter acompanhamento clínico e ultrassonográfico, para monitorar queixas, volume e crescimento dos miomas.","B":"proceder à miomectomia por via laparoscópica, dada a presença de miomas subserosos e intramurais concomitantes.","C":"realizar histerectomia com salpingectomia bilateral, dado o tamanho do útero, o histórico de gestações e a idade da paciente.","D":"indicar uso de antifibrinolítico no período da menstruação, para prevenir sangramentos abundantes devido aos miomas intramurais."},"answer":"A","explanation":"","needsVisualReview":true},{"id":"ginecologia-inep-069","number":69,"area":"Ginecologia","source":"INEP","sourceCode":"4000194325","stem":"Uma mulher leva sua Filha de 6 anos para uma consulta na unidade básica de saúde do bairro, por suspeitar que a Filha esteja sendo abusada sexualmente pelo tio de 24 anos de idade. O tio toma conta da menina quando ela se ausenta para trabalhar como faxineira. A menina conta que brinca de \"papai e mamãe\" com o tio, mas afirma não querer falar mais sobre o assunto, dizendo que o tio lhe havia dito que a “brincadeira” era um segredo apenas entre os dois. Com relação a situações de suspeita de abuso infantil, a exemplo da descrita, é correto afirmar que","options":{"A":"o mais comum é o agressor/abusador ser uma pessoa conhecida da família, ou um membro dela, o que favorece a repetição do abuso.","B":"os casos de abusos sexuais contra meninos são mais recorrentes do que contra meninas, pois eles tendem a esconder mais as agressões de que são vítimas.","C":"as crianças muito novas que sofrem abuso sexual tendem a esquecer o que aconteceu na fase adulta, havendo, portanto, pouca repercussão desse abuso no futuro.","D":"a equipe de saúde da família deve se restringir ao tratamento das lesões físicas e eventuais danos psicológicos, sem se envolver no encaminhamento da denúncia às autoridades policiais."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-070","number":70,"area":"Ginecologia","source":"INEP","sourceCode":"4000194266","stem":"Uma paciente com 35 anos, casada, nuligesta, procurou atendimento especializado, queixando-se de ciclos irregulares, fogachos, insônia, diminuição da lubrificação vaginal e da libido. O médico, após solicitação de exames e verificação dos resultados, fez o diagnóstico de insuficiência ovariana. Nesse caso, o diagnóstico pôde ser confirmado com base nos resultados dos seguintes exames:","options":{"A":"FSH e estradiol elevados, inibina baixa.","B":"FSH elevado, estradiol e inibina baixos.","C":"FSH baixo, estradiol e inibina elevados.","D":"FSH e estradiol baixos, inibina elevada."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-071","number":71,"area":"Ginecologia","source":"INEP","sourceCode":"4000194261","stem":"Os métodos contraceptivos hormonais femininos combinados são seguros e eficazes, porém devem ser prescritos por um médico ou profissional da saúde que faça parte de um serviço de planejamento familiar e que avalie se a paciente tem alguma contraindicação a esse uso. Segundo a OMS, com relação aos critérios de elegibilidade dos métodos contraceptivos orais combinados, categoria 4, assinale a opção correta.","options":{"A":"Não se deve utilizar o método de contraceptivos orais combinados, pois a contraindicação é absoluta, como no caso de cefaleia tensional.","B":"Não se deve utilizar o método de contraceptivos orais combinados, pois a contraindicação é absoluta, como no caso de trombofilia conhecida.","C":"Não é recomendado o uso de contraceptivos orais combinados, a menos que métodos mais adequados não estejam disponíveis ou não sejam aceitáveis, como no caso de presença de câncer de mama.","D":"Não é recomendado o uso de contraceptivos orais combinados, a menos que métodos mais adequados não estejam disponíveis ou não sejam aceitáveis, como nos casos de trombose venosa profunda ou de embolia pulmonar atual ou pregressa."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-072","number":72,"area":"Ginecologia","source":"INEP","sourceCode":"4000194251","stem":"Ao receber resultados de citologia realizada por mulheres de determinada comunidade em uma unidade básica de saúde (UBS), uma médica verifica que os resultados do exame de duas delas apresentaram lesão intraepitelial escamosa de alto grau. Ao entrar em contato com essas mulheres, a médica deve solicitar que","options":{"A":"retornem em 6 meses à UBS para repetição do exame.","B":"retornem imediatamente à UBS para repetição do exame.","C":"procurem o atendimento secundário para realização de colposcopia.","D":"procurem o atendimento secundário para realização de cirurgia de conização"},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-073","number":73,"area":"Ginecologia","source":"INEP","sourceCode":"4000178616","stem":"Mulher de 23 anos de idade procurou o ambulatório de ginecologia, com queixa de aumento da intensidade e duração do Fluxo menstrual há 8 meses. Nulípara, tem como antecedentes três abortos espontâneos, nos quais não precisou realizar curetagem uterina. No exame físico, não apresentou qualquer alteração. Apresentou os seguintes exames complementares recentes: - Colpocitologia oncológica: alterações celulares benignas reativas ou reparativas. - Ultrassonografia: volume uterino de 88 cm³. Eco endometrial heterogêneo de 36 mm (normalidade considerada até 15 mm) com lesão hiperecoica de contornos regulares na cavidade uterina. Anexos sem alterações ultrassonográficas. Considerando a história clínica e os exames físico e complementar da paciente, assinale a opção que apresenta a hipótese diagnóstica e a conduta adequada, respectivamente.","options":{"A":"Patologia cervical; colposcopia.","B":"Gestação ectópica; laparotomia exploratória.","C":"Miomatose uterina; laparoscopia diagnóstica.","D":"Pólipo endometrial; histeroscopia diagnóstica."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-074","number":74,"area":"Ginecologia","source":"INEP","sourceCode":"4000178611","stem":"A dispareunia é um problema comum na saúde da mulher e um distúrbio complexo que muitas vezes é negligenciado. Podendo ser classificado como de profundidade ou de penetração, geralmente leva a dificuldades sexuais como falta de desejo e de excitação sexual, resultando em um impacto significativo na saúde física e mental da mulher. Com relação à dispareunia, assinale a opção correta.","options":{"A":"Sua etiologia não engloba causas psicossociais, ficando restrita às causas anatômicas.","B":"Ela não guarda relação com a endometriose, cujos sintomas estão restritos ao período menstrual.","C":"A falta de lubrificação é uma causa comum e pode estar relacionada ao uso de contraceptivos hormonais.","D":"No subtipo de penetração, está restrita a causas infecciosas, como gonorreia, tricomoníase e vaginose bacteriana."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-075","number":75,"area":"Ginecologia","source":"INEP","sourceCode":"4000178601","stem":"Uma mulher de 30 anos de idade, G1P1, compareceu à unidade básica de saúde, para realização do exame citopatológico, sem queixas. Na ocasião, o exame ginecológico foi normal. A coleta da citologia oncótica, que mostrou o seguinte resultado: células glandulares atípicas de significado indeterminado (AGC), possivelmente não neoplásicas. O exame anterior, realizado havia 3 anos, não apresentava anormalidades. Nesse caso, a conduta adequada é","options":{"A":"realizar colposcopia.","B":"manter colpocitologia anual.","C":"fazer exérese da zona de transformação.","D":"repetir colpocitologia em exame em 6 meses."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-076","number":76,"area":"Ginecologia","source":"INEP","sourceCode":"4000178596","stem":"Uma mulher de 20 anos de idade, nuligesta, foi encaminhada para o pronto atendimento de um hospital universitário, com quadro de dor pélvica intermitente fazia uma semana. Havia 1 dia, a dor tornou-se mais intensa e constante. No exame físico, a paciente encontrava-se em bom estado geral, afebril, com pressão arterial de 110 × 70 mmHg, apresentando dor acentuada à palpação em fossa ilíaca direita. Os resultados do hemograma e do exame de urina foram normais e do teste de gravidez foi negativo. A ultrassonografia transvaginal mostrou uma imagem anecoica de 10 cm de diâmetro em ovário direito, com septação interna e sem fluxo ao doppler. O quadro clínico apresentado é característico de","options":{"A":"cisto torcido de ovário.","B":"abscesso tubo-ovariano.","C":"endometrioma de ovário.","D":"cisto hemorrágico ovariano."},"answer":"A","explanation":"","needsVisualReview":true},{"id":"ginecologia-inep-077","number":77,"area":"Ginecologia","source":"INEP","sourceCode":"4000178591","stem":"Uma mulher de 70 anos de idade compareceu ao ambulatório de ginecologia, queixando-se de prurido vulvar crônico e queimação local. No exame ginecológico, apresentava apagamento de pequenos lábios, uma área hipocrômica na face interna dos grandes lábios e região perineal, além de uma pequena lesão ulcerada em grande lábio direito, próximo ao clitóris. Assinale a opção que indica a hipótese diagnóstica desse caso e a conduta adequada, respectivamente.","options":{"A":"Cancroide; prescrever doxiciclina.","B":"Doença de Behçet; tratar com corticoide.","C":"Câncer de vulva; realizar biópsia da lesão.","D":"Neoplasia intravaginal (NIV) usual ou lesão intraepitelial de alto grau; exérese ampla da lesão."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-078","number":78,"area":"Ginecologia","source":"INEP","sourceCode":"4000178581","stem":"Uma mulher de 49 anos procurou uma unidade básica de saúde, com queixa de “caroço na mama esquerda” e saída de secreção esverdeada bilateralmente. No exame, notou-se um nódulo medindo 1,5 cm, indolor, na mama esquerda. As mamas não apresentavam alterações cutâneas ou adenopatia axilar. A paciente foi submetida a cirurgia com ressecção do tumor, cujo laudo histopatológico indicou carcinoma intraductal infiltrante, com 2 linfonodos sentinelas acometidos e receptores hormonais (progesterona e estrogênio) positivos. Assinale a opção que corresponde ao fator que demonstra o pior prognóstico para o quadro dessa paciente.","options":{"A":"Tipo histológico do tumor.","B":"Tamanho do tumor primário.","C":"Receptores hormonais positivos.","D":"Linfonodos sentinelas comprometidos."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-079","number":79,"area":"Ginecologia","source":"INEP","sourceCode":"4000178566","stem":"A síndrome do ovário policístico (SOP), caracterizada pela anovulação frequente, causa alterações menstruais importantes e quadros de infertilidade. Acerca dessa síndrome, assinale a opção correta.","options":{"A":"A insulinemia geralmente é abaixo do normal em paciente com essa síndrome, o que colabora para manifestações clínicas como o aparecimento das lesões do tipo acantose nigricans.","B":"A dopamina hipotalâmica aumentada na SOP inibe o hormônio liberador de gonadotrofina (GnRH), o que resulta em menor amplitude da secreção dos pulsos de hormônio luteinizante (LH) e, com isso, menores níveis de LH sistêmicos.","C":"O sulfato de deidroepiandrosterona (S-DHEA) marcadamente elevado é padrão-ouro para definição de SOP.","D":"A elevação do LH e a relação LH e do hormônio folículoestimulante (FSH) maior que 2,5 são achados observáveis na SOP."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-080","number":80,"area":"Ginecologia","source":"INEP","sourceCode":"4000178535","stem":"A equipe de uma unidade de saúde da família está organizando atividades educativas com a comunidade sobre métodos contraceptivos e planejamento familiar. Com relação aos direitos reprodutivos e sexuais na Atenção Primária à Saúde (APS), assinale a opção correta.","options":{"A":"A avaliação global e o acolhimento com escuta qualificada são função exclusiva dos médicos e enfermeiros na APS.","B":"É função específica da enfermagem a orientação com relação aos métodos contraceptivos de barreira.","C":"O método contraceptivo definitivo somente é aplicado para homem ou mulher com capacidade civil plena e que tenha idade acima de 25 anos e pelo menos dois filhos vivos.","D":"Para prescrição de anticoncepcional oral, não é necessária a realização prévia de colpocitologia oncótica nem exame de mamas."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-081","number":81,"area":"Ginecologia","source":"INEP","sourceCode":"4000178531","stem":"Paciente de 30 anos, com 25 semanas de gestação, portadora de diabetes mellitus tipo 1, compareceu a consulta no pré- natal de alto risco, com queixa de corrimento vaginal com prurido e ardência. Relatou também dispareunia de introito vaginal e disúria. No exame, confirmou-se a presença de eritema e Kssuras vulvares, corrimento grumoso, com placas aderidas à parede vaginal, de cor branca, edema vulvar e escoriações. Desde o início da gestação, a paciente já tinha tratado 4 vezes os mesmos sintomas. Qual é o tratamento a ser proposto para a paciente?","options":{"A":"Indução com fluconazol 150 mg, via oral, 1 vez ao dia, dias 1, 4 e 7. Manutenção com fluconazol 150 mg, via oral, 1 vez por semana, por 6 meses.","B":"Indução com itraconazol 100 mg, 2 comprimidos, via oral, 2 vezes ao dia, por 1 dia. Manutenção com miconazol óvulo vaginal, 1 vez por semana, durante 3 meses.","C":"Indução com miconazol creme vaginal tópico diário por 10 a 14 dias. Manutenção com miconazol creme vaginal tópico, 2 vezes por semana, durante 6 meses.","D":"Indução com miconazol creme vaginal tópico diário por 7 dias. Manutenção com miconazol óvulo vaginal, 1 vez por semana, durante 3 meses."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-082","number":82,"area":"Ginecologia","source":"INEP","sourceCode":"4000176679","stem":"Uma paciente com 42 anos de idade, gesta: 4, para: 3, aborto: 1, que fez laqueadura tubárea há 5 anos, comparece ao ambulatório com resultado de exame de citologia oncótica cérvico-vaginal sugestiva de lesão de alto grau. A colposcopia é satisfatória e pode ser observada área de mosaico grosseiro localizada no colo uterino, a 12 horas com 0,7 cm de diâmetro, visível em toda sua extensão. Em face desse contexto clínico, a conduta correta é indicar","options":{"A":"exérese da zona de transformação com alça de alta frequência.","B":"conização a frio do colo uterino com margem de segurança.","C":"repetição da coleta da citologia oncótica em 6 meses.","D":"amputação do colo uterino com eletrocauterização."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-083","number":83,"area":"Ginecologia","source":"INEP","sourceCode":"4000176674","stem":"Uma paciente com 46 anos de idade, gesta: 2, para: 2, aborto: 0, relata, em consulta em unidade de saúde, que há 8 meses vem apresentando aumento progressivo do volume e do número de dias de sangramento menstrual. Refere que atualmente sangra por cerca de 10 dias a cada ciclo. Queixa-se de indisposição física geral. Ao exame físico, está descorada +/4+. Ao exame ginecológico, a vulva, a vagina e o colo uterino apresentam-se normais, e o útero tem volume compatível com a idade e a paridade da paciente. No contexto clínico apresentado, considerando a maior redução de sangramento, qual a terapêutica a longo prazo recomendada?","options":{"A":"Ácido tranexâmico.","B":"Anti-inflamatório não esteroide.","C":"Anticoncepcional oral combinado.","D":"Sistema Intrauterino (SIU) com liberação de levonorgestrel."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-084","number":84,"area":"Ginecologia","source":"INEP","sourceCode":"4000176669","stem":"Uma paciente com 28 anos de idade, nulípara, usuária de anticoncepcional hormonal combinado oral, relata, em consulta, que há 3 dias iniciou com dor em baixo ventre, de forte intensidade, associada a náuseas e vômitos, que piorou nas últimas 8 horas. Ao exame físico, apresenta pressão arterial = 100 x 60 mmHg, temperatura = 39,1°C, abdome com dor intensa à palpação no andar inferior e à descompressão brusca em fossas ilíacas. Ao exame especular, verifica-se a presença de conteúdo purulento exteriorizando-se pelo orifício do colo uterino. O toque vaginal evidencia dor à mobilização do colo uterino e à palpação dos anexos, bilateralmente. Diante dessa situação, a conduta imediata indicada é","options":{"A":"identificar o agente etiológico da secreção cervical antes de iniciar o tratamento medicamentoso.","B":"encaminhar a paciente para tratamento em ambiente hospitalar com antibioticoterapia injetável.","C":"instituir tratamento clínico ambulatorial de imediato para a paciente, com retorno em 48 horas para reavaliação.","D":"encaminhar a paciente para tratamento cirúrgico a fim de melhor avaliar o comprometimento do sistema reprodutivo."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-085","number":85,"area":"Ginecologia","source":"INEP","sourceCode":"4000176644","stem":"Uma adolescente com 12 anos de idade, acompanhada de sua mãe chega a o plantão hospitalar c o m sangramento abundante. A mãe afirma que a menarca de sua Filha ocorreu há 6 meses. A adolescente relata ser a terceira menstruação nesse intervalo e nega contato sexual prévio. Ao exame ginecológico, não se observam anormalidades e o hímen está íntegro. Considerando esse quadro clínico, a causa mais provável de sangramento uterino anormal da paciente é","options":{"A":"anovulação.","B":"doença von Willebrand.","C":"hipogonadismo hipogonadotrófico.","D":"púrpura trombocitopênica idiopática."},"answer":"A","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-086","number":86,"area":"Ginecologia","source":"INEP","sourceCode":"4000176639","stem":"Na Unidade Básica de Saúde, uma paciente com 28 anos de idade relata novo relacionamento e desejo de uma nova gravidez. Nega intercorrências nas três gestações passadas, informando ter realizado laqueadura tubária no último parto, há 3 anos. Relata também que seus ciclos são regulares e que o exame ginecológico não apresentou alterações significativas. Acrescenta que o atual companheiro também tem um filho de união anterior, o qual tem 8 anos de idade. No projeto terapêutico direcionado ao casal, qual deverá ser a indicação inicial?","options":{"A":"Encaminhar o casal para programa de adoção.","B":"Prescrever indução de ovulação para reprodução assistida.","C":"Encaminhar a paciente para cirurgia de recanalização tubária.","D":"Solicitar exames para excluir outros fatores de infertilidade."},"answer":"D","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-087","number":87,"area":"Ginecologia","source":"INEP","sourceCode":"4000176634","stem":"Uma paciente com 19 anos de idade, solteira, busca orientação médica em Unidade Básica de Saúde. Relata que teve duas gestações anteriores, sendo um parto a termo e um aborto, e que tem um Filho vivo e saudável de 3 anos de idade. Informa que contraiu infecção pelo HIV há 2 anos e utiliza terapia antirretroviral há 6 meses. Está assintomática e sem sinais clínicos de patologias. Os exames de rotina mostram contagens de LT-CD4+ acima de 500 células/mm³ e carga virai indetectável. Ela refere início de um relacionamento com parceiro soropositivo de 35 anos de idade há 1 mês. Refere, ainda, que o parceiro tem dois filhos vivos saudáveis e que o casal não deseja ter filhos. Nessa situação, está indicado","options":{"A":"realização de laqueadura tubária associada ao uso de preservativo.","B":"uso de anticoncepcional hormonal associado ao uso de preservativo.","C":"uso do Dispositivo Intrauterino (DIU) de cobre.","D":"realização de vasectomia."},"answer":"B","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-088","number":88,"area":"Ginecologia","source":"INEP","sourceCode":"4000176629","stem":"Uma mulher com 25 anos de idade, casada, atendida em uma Unidade Básica de Saúde, queixa-se de sangramentos intermenstruais nos últimos meses. A paciente relata que mudou de contraceptivo hormonal oral (CHO) por sua própria iniciativa há 3 meses: usava CHO composto por etinilestradiol 35 mcg em associação com acetato de ciproterona 2 mg e mudou para CHO composto por etinilestradiol 20 mcg em associação com gestodeno 75 mcg. Ela tem como antecedentes relevantes ser multigesta (2 partos normais, o último há 3 anos) e apresenta quadro de convulsões tônico- cônicas controladas com o uso de anticonvulsivante fenitoína 300 mg ao dia. Diante desse quadro clínico, a orientação que deve ser dada à paciente para corrigir o problema é","options":{"A":"usar fármacos que reduzam o sangramento na fase dos sangramentos intermenstruais, por exemplo, anti- inflamatórios e/ou antifibrinolíticos.","B":"voltar a fazer uso de CHO de dose maior, podendo ser o mesmo que usava antes (etinilestradiol 35 mcg em associação com acetato de ciproterona 2 mg).","C":"inserir o Dispositivo Intrauterino (DIU), pois existe contraindicação ao uso de métodos hormonais estroprogestativos por via oral.","D":"usar outro CHO com o progestógeno acetato de ciproterona, pois o gestodeno frequentemente se associa com maior risco de sangramentos intermenstruais."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-089","number":89,"area":"Ginecologia","source":"INEP","sourceCode":"4000176624","stem":"Uma paciente com 25 anos de idade, casada há 3 meses, usa Dispositivo Intrauterino (DIU) como método anticoncepcional. Procura consulta em centro de saúde com queixa de corrimento vaginal abundante. Refere que a secreção é amarelada, que sente ardor e dor, que piora na relação sexual. Ao exame ginecológico, é observada hiperemia de genitais externos e de parede vaginal, com presença de secreção amarelo-esverdeada com pequenas bolhas, não aderida à parede vaginal, além de colo uterino com colpite e \"aspecto de morango\". Nesse caso, o exame a ser realizado e seu resultado mais provável são, respectivamente,","options":{"A":"exame de secreção vaginal com coloração de Gram; observadas \"Clue Cells\".","B":"cultura de secreção vaginal; observado crescimento de Streptococcus agalactie.","C":"exame a fresco de secreção vaginal; observados parasitas flagelados com movimentos pendulares.","D":"exame a fresco de secreção vaginal com hidróxido de potássio; observadas pseudo-hifas e esporos."},"answer":"C","explanation":"","needsVisualReview":false},{"id":"ginecologia-inep-090","number":90,"area":"Ginecologia","source":"INEP","sourceCode":"4000176619","stem":"Uma paciente com 62 anos de idade comparece à consulta no centro de saúde com o laudo de exame de ultrassom pélvico. No laudo, constam a descrição de um cisto com septação espessa, ecogenicidade aumentada e com projeção papilar em ovário esquerdo; ausência de ascite ou outros achados, medidas uterinas e do ovário direito normais. A paciente acrescenta que desconhece histórico familiar de cistos ou tumores de ovário. Considerando o caso clínico apresentado, assinale a opção correta.","options":{"A":"As características ultrassonográficas são de alto risco para malignidade.","B":"As características ultrassonográficas correspondem a processos não neoplásicos ou fisiológicos.","C":"As características ultrassonográficas são inespecíficas para classificar risco de malignidade.","D":"O exame de ultrassom não é adequado para a avaliação das características da massa anexial."},"answer":"A","explanation":"","needsVisualReview":false}]);
